import{_ as r,a0 as i,w as p,s as b,ao as s,I as o,x as l,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器 | LCTT x X-CMD","titleTemplate":false,"description":"shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator","title":"shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器","tag":"201508","desc":""},"relativePath":"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator.md","filePath":"[post].md"}'),d={name:"201508/20150816 shellinabox--A Web based AJAX Terminal Emulator.md"};function h(x,e,u,m,A,E){const n=i("Link");return p(),b("div",null,[e[25]||(e[25]=s('<h1 id="shellinabox-一款使用-ajax-的基于-web-的终端模拟器" tabindex="-1">shellinabox：一款使用 AJAX 的基于 Web 的终端模拟器 <a class="header-anchor" href="#shellinabox-一款使用-ajax-的基于-web-的终端模拟器" aria-label="Permalink to “shellinabox：一款使用  AJAX 的基于 Web 的终端模拟器”">​</a></h1><h3 id="shellinabox简介" tabindex="-1">shellinabox简介 <a class="header-anchor" href="#shellinabox简介" aria-label="Permalink to “shellinabox简介”">​</a></h3><p>通常情况下，我们在访问任何远程服务器时，会使用常见的通信工具如OpenSSH和Putty等。但是，有可能我们在防火墙后面不能使用这些工具访问远程系统，或者防火墙只允许HTTPS流量才能通过。不用担心！即使你在这样的防火墙后面，我们依然有办法来访问你的远程系统。而且，你不需要安装任何类似于OpenSSH或Putty的通讯工具。你只需要有一个支持JavaScript和CSS的现代浏览器，并且你不用安装任何插件或第三方应用软件。</p><p>这个 <strong>Shell In A Box</strong>，发音是<strong>shellinabox</strong>，是由<strong>Markus Gutschke</strong>开发的一款自由开源的基于Web的Ajax的终端模拟器。它使用AJAX技术，通过Web浏览器提供了类似原生的 Shell 的外观和感受。</p>',4)),o("p",null,[e[1]||(e[1]=l("这个",-1)),e[2]||(e[2]=o("strong",null,"shellinaboxd",-1)),e[3]||(e[3]=l("守护进程实现了一个Web服务器，能够侦听指定的端口。其Web服务器可以发布一个或多个服务，这些服务显示在用 AJAX Web 应用实现的VT100模拟器中。默认情况下，端口为4200。你可以更改默认端口到任意选择的任意端口号。在你的远程服务器安装shellinabox以后，如果你想从本地系统接入，打开Web浏览器并导航到：**",-1)),t(n,{href:"http://IP-Address:4200/**%E3%80%82%E8%BE%93%E5%85%A5%E4%BD%A0%E7%9A%84%E7%94%A8%E6%88%B7%E5%90%8D%E5%92%8C%E5%AF%86%E7%A0%81%EF%BC%8C%E7%84%B6%E5%90%8E%E5%B0%B1%E5%8F%AF%E4%BB%A5%E5%BC%80%E5%A7%8B%E4%BD%BF%E7%94%A8%E4%BD%A0%E8%BF%9C%E7%A8%8B%E7%B3%BB%E7%BB%9F%E7%9A%84Shell%E3%80%82%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%BE%88%E6%9C%89%E8%B6%A3%EF%BC%8C%E4%B8%8D%E6%98%AF%E5%90%97%EF%BC%9F%E7%A1%AE%E5%AE%9E"},{default:a(()=>[...e[0]||(e[0]=[l("http://IP-Address:4200/**。输入你的用户名和密码，然后就可以开始使用你远程系统的Shell。看起来很有趣，不是吗？确实",-1)])]),_:1}),e[4]||(e[4]=l(" 有趣！",-1))]),e[26]||(e[26]=s(`<p><strong>免责声明</strong>:</p><p>shellinabox不是SSH客户端或任何安全软件。它仅仅是一个应用程序，能够通过Web浏览器模拟一个远程系统的Shell。同时，它和SSH没有任何关系。这不是可靠的安全地远程控制您的系统的方式。这只是迄今为止最简单的方法之一。无论如何，你都不应该在任何公共网络上运行它。</p><h3 id="安装shellinabox" tabindex="-1">安装shellinabox <a class="header-anchor" href="#安装shellinabox" aria-label="Permalink to “安装shellinabox”">​</a></h3><h4 id="在debian-ubuntu系统上" tabindex="-1">在Debian / Ubuntu系统上： <a class="header-anchor" href="#在debian-ubuntu系统上" aria-label="Permalink to “在Debian / Ubuntu系统上：”">​</a></h4><p>shellinabox在默认库是可用的。所以，你可以使用命令来安装它：</p><pre><code>$ sudo apt-get install shellinabox
</code></pre><h4 id="在rhel-centos系统上" tabindex="-1">在RHEL / CentOS系统上： <a class="header-anchor" href="#在rhel-centos系统上" aria-label="Permalink to “在RHEL / CentOS系统上：”">​</a></h4><p>首先，使用命令安装EPEL仓库：</p><pre><code># yum install epel-release
</code></pre><p>然后，使用命令安装shellinabox：</p><pre><code># yum install shellinabox
</code></pre><p>完成！</p><h3 id="配置shellinabox" tabindex="-1">配置shellinabox <a class="header-anchor" href="#配置shellinabox" aria-label="Permalink to “配置shellinabox”">​</a></h3><p>正如我之前提到的，shellinabox侦听端口默认为<strong>4200</strong>。你可以将此端口更改为任意数字，以防别人猜到。</p><p>在Debian/Ubuntu系统上shellinabox配置文件的默认位置是<strong>/etc/default/shellinabox</strong>。在RHEL/CentOS/Fedora上，默认位置在<strong>/etc/sysconfig/shellinaboxd</strong>。</p><p>如果要更改默认端口，</p><p>在Debian / Ubuntu：</p><pre><code>$ sudo vi /etc/default/shellinabox
</code></pre><p>在RHEL / CentOS / Fedora：</p><pre><code># vi /etc/sysconfig/shellinaboxd
</code></pre><p>更改你的端口到任意数字。因为我在本地网络上测试它，所以我使用默认值。</p><pre><code># Shell in a box daemon configuration
# For details see shellinaboxd man page

# Basic options
USER=shellinabox
GROUP=shellinabox
CERTDIR=/var/lib/shellinabox
PORT=4200
OPTS=&quot;--disable-ssl-menu -s /:LOGIN&quot;

# Additional examples with custom options:

# Fancy configuration with right-click menu choice for black-on-white:
# OPTS=&quot;--user-css Normal:+black-on-white.css,Reverse:-white-on-black.css --disable-ssl-menu -s /:LOGIN&quot;

# Simple configuration for running it as an SSH console with SSL disabled:
# OPTS=&quot;-t -s /:SSH:host.example.com&quot;
</code></pre><p>重启shelinabox服务。</p><p><strong>在Debian/Ubuntu:</strong></p><pre><code>$ sudo systemctl restart shellinabox
</code></pre><p>或者</p><pre><code>$ sudo service shellinabox restart
</code></pre><p>在RHEL/CentOS系统，运行下面的命令能在每次重启时自动启动shellinaboxd服务</p><pre><code># systemctl enable shellinaboxd
</code></pre><p>或者</p><pre><code># chkconfig shellinaboxd on
</code></pre><p>如果你正在运行一个防火墙，记得要打开端口<strong>4200</strong>或任何你指定的端口。</p><p>例如，在RHEL/CentOS系统，你可以如下图所示允许端口。</p><pre><code># firewall-cmd --permanent --add-port=4200/tcp
</code></pre><hr><pre><code># firewall-cmd --reload
</code></pre><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3>`,37)),o("p",null,[e[6]||(e[6]=l("现在，在你的客户端系统，打开Web浏览器并导航到：",-1)),o("strong",null,[t(n,{href:"https://ip-address-of-remote-servers:4200"},{default:a(()=>[...e[5]||(e[5]=[l("https://ip-address-of-remote-servers:4200",-1)])]),_:1})]),e[7]||(e[7]=l("。",-1))]),e[27]||(e[27]=s(`<p><strong>注意</strong>：如果你改变了端口，请填写修改后的端口。</p><p>你会得到一个证书问题的警告信息。接受该证书并继续。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/Privacy-error-Google-Chrome_001.jpg" alt="Privacy error - Google Chrome_001"></p><p>输入远程系统的用户名和密码。现在，您就能够从浏览器本身访问远程系统的外壳。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_003.jpg" alt="Shell In A Box - Google Chrome_003"></p><p>右键点击你浏览器的空白位置。你可以得到一些有很有用的额外菜单选项。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_004.jpg" alt="Shell In A Box - Google Chrome_004"></p><p>从现在开始，你可以通过本地系统的Web浏览器在你的远程服务器随意操作。</p><p>当你完成工作时，记得输入<code>exit</code>退出。</p><p>当再次连接到远程系统时，单击<strong>连接</strong>按钮，然后输入远程服务器的用户名和密码。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/sk@server1-Shell-In-A-Box-Google-Chrome_005.jpg" alt="Shell In A Box - Google Chrome_005"></p><p>如果想了解shellinabox更多细节，在你的终端键入下面的命令：</p><pre><code># man shellinabox
</code></pre><p>或者</p><pre><code># shellinaboxd -help
</code></pre>`,15)),o("p",null,[e[9]||(e[9]=l("同时，参考",-1)),t(n,{href:"https://code.google.com/p/shellinabox/wiki/shellinaboxd_man"},{default:a(()=>[...e[8]||(e[8]=[l("shellinabox 在wiki页面的介绍",-1)])]),_:1}),e[10]||(e[10]=l("，来了解shellinabox的综合使用细节。",-1))]),e[28]||(e[28]=o("h3",{id:"结论",tabindex:"-1"},[l("结论 "),o("a",{class:"header-anchor",href:"#结论","aria-label":"Permalink to “结论”"},"​")],-1)),e[29]||(e[29]=o("p",null,"正如我之前提到的，如果你在服务器运行在防火墙后面，那么基于web的SSH工具是非常有用的。有许多基于web的SSH工具，但shellinabox是非常简单而有用的工具，可以从的网络上的任何地方，模拟一个远程系统的Shell。因为它是基于浏览器的，所以你可以从任何设备访问您的远程服务器，只要你有一个支持JavaScript和CSS的浏览器。",-1)),e[30]||(e[30]=o("p",null,"就这些啦。祝你今天有个好心情！",-1)),e[31]||(e[31]=o("h4",{id:"参考链接",tabindex:"-1"},[l("参考链接： "),o("a",{class:"header-anchor",href:"#参考链接","aria-label":"Permalink to “参考链接：”"},"​")],-1)),o("ul",null,[o("li",null,[t(n,{href:"https://code.google.com/p/shellinabox/"},{default:a(()=>[...e[11]||(e[11]=[l("shellinabox website",-1)])]),_:1})])]),e[32]||(e[32]=o("hr",null,null,-1)),o("p",null,[e[13]||(e[13]=l("via: ",-1)),t(n,{href:"http://www.unixmen.com/shellinabox-a-web-based-ajax-terminal-emulator/"},{default:a(()=>[...e[12]||(e[12]=[l("http://www.unixmen.com/shellinabox-a-web-based-ajax-terminal-emulator/",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=l("作者：",-1)),t(n,{href:"http://www.unixmen.com/author/sk/"},{default:a(()=>[...e[14]||(e[14]=[l("SK",-1)])]),_:1}),e[18]||(e[18]=l(" 译者：",-1)),t(n,{href:"https://github.com/xiaoyu33"},{default:a(()=>[...e[15]||(e[15]=[l("xiaoyu33",-1)])]),_:1}),e[19]||(e[19]=l(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[16]||(e[16]=[l("wxy",-1)])]),_:1})]),o("p",null,[e[22]||(e[22]=l("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[20]||(e[20]=[l("LCTT",-1)])]),_:1}),e[23]||(e[23]=l(" 原创翻译，",-1)),t(n,{href:"http://linux.cn/"},{default:a(()=>[...e[21]||(e[21]=[l("Linux中国",-1)])]),_:1}),e[24]||(e[24]=l(" 荣誉推出",-1))])])}const C=r(d,[["render",h]]);export{f as __pageData,C as default};
